      "n4b": {"npc":"Ingen fester på hverdage, og der skal være ro efter klokken 23. Det passer alle fint.","it":"Niente feste nei giorni feriali e silenzio dopo le 23. Va bene a tutti.","hint":"Di' che per te va bene.","replies":[{"say":["Det lyder fint. Det er helt i orden for mig.","Det er fint for mig.","Det passer mig fint."],"it":"Mi sembra giusto. Per me va benissimo.","next":"n5"}],"wrong":[{"say":"Det passer for mig fint.","why":"Si dice «det passer mig fint»: pronome subito dopo il verbo, senza «for», e «fint» alla fine."},{"say":"Det lyder fin.","why":"«det lyder fint»: aggettivo neutro."}],"fallback":"n4b_f"},
      "n4b_f": {"npc":"Ro efter klokken 23.","it":"Silenzio dopo le 23.","hint":"Di' che per te va bene.","replies":[{"say":["Det lyder fint. Det er helt i orden for mig.","Det er fint for mig.","Det passer mig fint."],"it":"Mi sembra giusto. Per me va benissimo.","next":"n5"}],"wrong":[{"say":"Det passer for mig fint.","why":"Si dice «det passer mig fint»: pronome subito dopo il verbo, senza «for», e «fint» alla fine."},{"say":"Det lyder fin.","why":"«det lyder fint»: aggettivo neutro."}],"fallback":"n4b_f"},
