      "n5_f": {"npc":"Hvad laver du? Studerer du?","it":"Che fai? Studi?","hint":"Di' cosa fai e che tipo di coinquilino sei.","replies":[{"say":["Jeg læser økonomi og arbejder i en café i weekenden.","Jeg studerer økonomi og har et studiejob i weekenden."],"it":"Studio economia e lavoro in un caffè nel weekend.","next":"n6"},{"say":["Jeg er italiener og læser økonomi. Jeg er stille og ryddelig.","Jeg kommer fra Italien, læser økonomi og er ret ryddelig."],"it":"Sono italiano e studio economia. Sono tranquillo e ordinato.","next":"n6"}],"wrong":[{"say":"Jeg studerer på økonomi.","why":"Si dice «læse/studere økonomi» senza preposizione."},{"say":"Jeg arbejder i en café på weekenden.","why":"Per «nel fine settimana» si dice «i weekenden» (non «på weekenden»)."}],"fallback":"n5_f"},
